SELECT

FROM product
WHERE company_id = #{companyId}


    AND (
    LOWER(product_code)
    LIKE '%' || LOWER(#{keyword}) || '%'
    OR LOWER(product_name)
    LIKE '%' || LOWER(#{keyword}) || '%'
    )



    AND lot_managed_yn = #{lotManagedYn}



    AND tax_type = #{taxType}



    AND storage_type = #{storageType}



    AND use_yn = #{useYn}


ORDER BY
use_yn DESC,
product_name ASC,
product_id ASC

SELECT

FROM product
WHERE company_id = #{companyId}
AND product_id = #{productId}

SELECT COUNT(*)
FROM product
WHERE company_id = #{companyId}
AND LOWER(TRIM(product_code))
= LOWER(TRIM(#{productCode}))


    AND product_id != #{excludeProductId}

mapper.update:
UPDATE product
SET product_code = #{productCode},
product_name = #{productName},
lot_managed_yn = #{lotManagedYn},
tax_type = #{taxType},
storage_type = #{storageType},
updated_at = CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
),
updated_by = #{updatedBy}
WHERE product_id = #{productId}
AND company_id = #{companyId}

UPDATE product
SET use_yn = #{useYn},
updated_at = CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
),
updated_by = #{updatedBy}
WHERE product_id = #{productId}
AND company_id = #{companyId}
